SELECT r.report_id, r.namespace_id, r.version_no, r.state, r.authoring_mode, r.authored_sql, r.authored_dql, r.component_spec_json, r.spec_format_version, r.spec_hash, r.generated_dql, r.dql_export_limits_json, r.type_manifest_json, r.resource_manifest_json, r.component_descriptor_json, r.compile_status, r.compile_diagnostics_json, r.datly_version, r.compiler_version, r.source_revision, r.notes, r.created_by, r.created_at, r.validated_at, r.published_at FROM (SELECT report_version.report_id, report_version.namespace_id, report_version.version_no, report_version.state, report_version.authoring_mode, report_version.authored_sql, report_version.authored_dql, report_version.component_spec_json, report_version.spec_format_version, report_version.spec_hash, report_version.generated_dql, report_version.dql_export_limits_json, report_version.type_manifest_json, report_version.resource_manifest_json, report_version.component_descriptor_json, report_version.compile_status, report_version.compile_diagnostics_json, report_version.datly_version, report_version.compiler_version, report_version.source_revision, report_version.notes, report_version.created_by, report_version.created_at, report_version.validated_at, report_version.published_at FROM component_versions report_version WHERE $criteria.In("report_version.report_id", $ComponentIds.Values)  ORDER BY report_version.report_id, report_version.version_no
#if($ComponentIds.Values) ${View.ForUpdate()} #end) r WHERE $criteria.CompositeIn("r", $VersionKeys)